/**
 * Apache / LiteSpeed rules for Next.js static export (trailingSlash: true).
 */
export function buildHtaccess(redirects, gonePaths) {
  const lines = [
    "# Zahnspange Sablania — generated by npm run build:cpanel",
    "Options -Indexes +FollowSymLinks",
    "DirectoryIndex index.html",
    "",
    "ErrorDocument 404 /404.html",
    "",
    "<IfModule mod_rewrite.c>",
    "  RewriteEngine On",
    "  RewriteBase /",
    "",
    "  # Existing files (images, .html, _next/static, etc.)",
    "  RewriteCond %{REQUEST_FILENAME} -f",
    "  RewriteRule ^ - [L]",
    "",
  ];

  for (const p of gonePaths) {
    const withoutLeading = p.slice(1);
    const escaped = withoutLeading.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    lines.push(`  RewriteRule ^${escaped}/?$ - [R=410,L]`);
  }

  lines.push("");
  for (const r of redirects) {
    const from = r.source.replace(/^\//, "").replace(/\//g, "\\/");
    let to = r.destination.startsWith("/") ? r.destination : `/${r.destination}`;
    if (!to.endsWith("/")) {
      to = `${to}/`;
    }
    lines.push(`  RewriteRule ^${from}/?$ ${to} [R=301,L]`);
  }

  lines.push(
    "",
    "  # Next.js export: each route is a folder with index.html",
    "  RewriteCond %{REQUEST_FILENAME} !-f",
    "  RewriteCond %{DOCUMENT_ROOT}/$1/index.html -f",
    "  RewriteRule ^(.+)/$ $1/index.html [L]",
    "",
    "  RewriteCond %{REQUEST_FILENAME} !-f",
    "  RewriteCond %{DOCUMENT_ROOT}/$1/index.html -f",
    "  RewriteRule ^(.+[^/])$ $1/index.html [L]",
    "",
    "  RewriteCond %{DOCUMENT_ROOT}/$1/index.html -f",
    "  RewriteRule ^(.+[^/])$ /$1/ [R=301,L]",
    "",
    "  RewriteRule ^$ index.html [L]",
    "</IfModule>",
    "",
  );

  return lines.join("\n");
}
